SET search_path = maker3d, pg_catalog;
CREATE TABLE IF NOT EXISTS gallery_items(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,project_id INTEGER UNIQUE REFERENCES projects(id),status TEXT NOT NULL CHECK(status IN ('pending','published','hidden','declined')),title TEXT NOT NULL,collection TEXT NOT NULL,note TEXT,site TEXT,url TEXT,author TEXT,license TEXT,license_checked_by INTEGER REFERENCES users(id),license_checked_at TEXT,site_image_key TEXT,site_image_mime TEXT,photo_key TEXT,photo_mime TEXT,minutes INTEGER,grams REAL,material TEXT,size TEXT,maker TEXT,authorized_by INTEGER REFERENCES users(id),authorized_at TEXT,created_by INTEGER NOT NULL REFERENCES users(id),created TEXT NOT NULL,updated TEXT NOT NULL);
ALTER TABLE gallery_items ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS maker3d_backend ON gallery_items;
CREATE POLICY maker3d_backend ON gallery_items TO maker3d_app USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON gallery_items TO maker3d_app;
REVOKE ALL ON gallery_items FROM PUBLIC, anon, authenticated;
RESET search_path;
